static void aw_FatEQ_init_fast(void *aw_state, double aw_rate) {
    aw_FatEQ_fast_t *aw_s = (aw_FatEQ_fast_t *)aw_state;
    memset(aw_s, 0, sizeof(*aw_s));
    aw_s->aw_sample_rate = aw_rate;
    aw_s->aw_rand = AW_RAND_SEED;
    const double aw_sample_rate = aw_rate;
    (void)aw_sample_rate;
    float A = aw_s->A;
    float B = aw_s->B;
    float C = aw_s->C;
    float D = aw_s->D;
    float E = aw_s->E;
    float *pearA = aw_s->pearA;
    float *pearB = aw_s->pearB;
    float *pearC = aw_s->pearC;
    float lastSampleL = aw_s->lastSampleL;
    float *intermediateL = aw_s->intermediateL;
    bool wasPosClipL = aw_s->wasPosClipL;
    bool wasNegClipL = aw_s->wasNegClipL;
    float lastSampleR = aw_s->lastSampleR;
    float *intermediateR = aw_s->intermediateR;
    bool wasPosClipR = aw_s->wasPosClipR;
    bool wasNegClipR = aw_s->wasNegClipR;
    uint32_t fpdL = aw_s->fpdL;
    uint32_t fpdR = aw_s->fpdR;
    uint32_t aw_rand = aw_s->aw_rand;
    {
	A = 0.5;
	B = 0.5;
	C = 0.5;
	D = 0.5;
	E = 1.0;
	
	for (int x = 0; x < pear_total; x++) {
		pearA[x] = 0.0;
		pearB[x] = 0.0;
		pearC[x] = 0.0;
	}	
	
	lastSampleL = 0.0;
	wasPosClipL = false;
	wasNegClipL = false;
	lastSampleR = 0.0;
	wasPosClipR = false;
	wasNegClipR = false;
	for (int x = 0; x < 16; x++) {intermediateL[x] = 0.0; intermediateR[x] = 0.0;}	

	fpdL = 1.0; fpdL = aw_seed(0);
	fpdR = 1.0; fpdR = aw_seed(1); // default program name
	aw_rand = AW_RAND_SEED;
}
    aw_s->A = A;
    aw_s->B = B;
    aw_s->C = C;
    aw_s->D = D;
    aw_s->E = E;
    aw_s->lastSampleL = lastSampleL;
    aw_s->wasPosClipL = wasPosClipL;
    aw_s->wasNegClipL = wasNegClipL;
    aw_s->lastSampleR = lastSampleR;
    aw_s->wasPosClipR = wasPosClipR;
    aw_s->wasNegClipR = wasNegClipR;
    aw_s->fpdL = fpdL;
    aw_s->fpdR = fpdR;
    aw_s->aw_rand = aw_rand;
}

static void aw_FatEQ_process_fast(void *aw_state, int16_t *aw_out,
    const int16_t *aw_in, int32_t sampleFrames, uint32_t aw_channels) {
    aw_FatEQ_fast_t *aw_s = (aw_FatEQ_fast_t *)aw_state;
    const double aw_sample_rate = aw_s->aw_sample_rate;
    (void)aw_sample_rate;
    float A = aw_s->A;
    float B = aw_s->B;
    float C = aw_s->C;
    float D = aw_s->D;
    float E = aw_s->E;
    float *pearA = aw_s->pearA;
    float *pearB = aw_s->pearB;
    float *pearC = aw_s->pearC;
    float lastSampleL = aw_s->lastSampleL;
    float *intermediateL = aw_s->intermediateL;
    bool wasPosClipL = aw_s->wasPosClipL;
    bool wasNegClipL = aw_s->wasNegClipL;
    float lastSampleR = aw_s->lastSampleR;
    float *intermediateR = aw_s->intermediateR;
    bool wasPosClipR = aw_s->wasPosClipR;
    bool wasNegClipR = aw_s->wasNegClipR;
    uint32_t fpdL = aw_s->fpdL;
    uint32_t fpdR = aw_s->fpdR;
    {

	double overallscale = 1.0;
	overallscale /= 44100.0;
	overallscale *= aw_sample_rate;
	int spacing = floor(overallscale); //should give us working basic scaling, usually 2 or 4
	if (spacing < 1) spacing = 1; if (spacing > 16) spacing = 16;
	
	double topLevl = A*2.0; if (topLevl < 1.0) topLevl = sqrt(topLevl);
	pearA[levl] = B*2.0; if (pearA[levl] < 1.0) pearA[levl] = sqrt(pearA[levl]);
	pearB[levl] = C*2.0; if (pearB[levl] < 1.0) pearB[levl] = sqrt(pearB[levl]);
	pearC[levl] = D*2.0; if (pearC[levl] < 1.0) pearC[levl] = sqrt(pearC[levl]);
	double out = E;
	
	double freqFactor = sqrt(overallscale) + (overallscale*0.5);
	pearA[freq] = pow(0.564,freqFactor+0.85);
	pearB[freq] = pow(0.564,freqFactor+4.1);
	pearC[freq] = pow(0.564,freqFactor+7.1);
	
    const float aw_f_topLevl = (float)topLevl;
	const float aw_f_out = (float)out;
	const float aw_inv0 = 1.0f / (6.0f);
	const float aw_inv1 = 1.0f / ( 120.0f);
	const float aw_inv2 = 1.0f / ( 5040.0f);
	const float aw_inv3 = 1.0f / ( 362880.0f);
	const float aw_inv4 = 1.0f / ( 39916800.0f);
	const float aw_inv5 = 1.0f / ( 2.0f);
	const float aw_inv6 = 1.0f / ( 24.0f);
	const float aw_inv7 = 1.0f / ( 720.0f);
	const float aw_inv8 = 1.0f / ( 40320.0f);
	const float aw_inv9 = 1.0f / ( 3628800.0f);
	while (--sampleFrames >= 0)
    {
		const float aw_inL = AW_IN_L(aw_in);
		const float aw_inR = AW_IN_R(aw_in, aw_channels);
		float aw_outL = 0.0f, aw_outR = 0.0f;/* aw:loop */
		float inputSampleL = aw_inL;
		float inputSampleR = aw_inR;
		if (fabsf(inputSampleL)<1.18e-23f) inputSampleL = fpdL * 1.18e-17f;
		if (fabsf(inputSampleR)<1.18e-23f) inputSampleR = fpdR * 1.18e-17f;
		
		for (int x = 0; x < pear_max; x += 4) {
			//begin Pear filter stages
			pearA[figL] = inputSampleL; pearA[figR] = inputSampleR;
			pearA[slew] = ((pearA[figL]-pearA[x])+pearA[x+1])*pearA[freq]*0.5f;
			pearA[x] = pearA[figL] = (pearA[freq]*pearA[figL])+((1.0f-pearA[freq])*(pearA[x]+pearA[x+1]));
			pearA[x+1] = pearA[slew];
			pearA[slew] = ((pearA[figR]-pearA[x+2])+pearA[x+3])*pearA[freq]*0.5f;
			pearA[x+2] = pearA[figR] = (pearA[freq]*pearA[figR])+((1.0f-pearA[freq])*(pearA[x+2]+pearA[x+3]));
			pearA[x+3] = pearA[slew];
			inputSampleL -= pearA[figL]; inputSampleR -= pearA[figR];
			
			pearB[figL] = pearA[figL]; pearB[figR] = pearA[figR];
			pearB[slew] = ((pearB[figL]-pearB[x])+pearB[x+1])*pearB[freq]*0.5f;
			pearB[x] = pearB[figL] = (pearB[freq]*pearA[figL])+((1.0f-pearB[freq])*(pearB[x]+pearB[x+1]));
			pearB[x+1] = pearB[slew];
			pearB[slew] = ((pearB[figR]-pearB[x+2])+pearB[x+3])*pearB[freq]*0.5f;
			pearB[x+2] = pearB[figR] = (pearB[freq]*pearA[figR])+((1.0f-pearB[freq])*(pearB[x+2]+pearB[x+3]));
			pearB[x+3] = pearB[slew];
			pearA[figL] -= pearB[figL]; pearA[figR] -= pearB[figR];
			
			pearC[figL] = pearB[figL]; pearC[figR] = pearB[figR];
			pearC[slew] = ((pearC[figL]-pearC[x])+pearC[x+1])*pearC[freq]*0.5f;
			pearC[x] = pearC[figL] = (pearC[freq]*pearB[figL])+((1.0f-pearC[freq])*(pearC[x]+pearC[x+1]));
			pearC[x+1] = pearC[slew];
			pearC[slew] = ((pearC[figR]-pearC[x+2])+pearC[x+3])*pearC[freq]*0.5f;
			pearC[x+2] = pearC[figR] = (pearC[freq]*pearB[figR])+((1.0f-pearC[freq])*(pearC[x+2]+pearC[x+3]));
			pearC[x+3] = pearC[slew];
			pearB[figL] -= pearC[figL]; pearB[figR] -= pearC[figR];
			
			//begin FatEQL
			float altered = inputSampleL;
			if (aw_f_topLevl > 1.0f) {
				altered = fmaxf(fminf(inputSampleL*(1.57079632679489661923f),(1.57079632679489661923f)),-(1.57079632679489661923f));
				float X = altered*altered;
				float temp = altered*X; altered -= (temp* aw_inv0); temp *= X;
				altered += (temp * aw_inv1); temp *= X; altered -= (temp * aw_inv2); temp *= X;
				altered += (temp * aw_inv3); temp *= X; altered -= (temp * aw_inv4);
			}
			if (aw_f_topLevl < 1.0f) {
				altered = fmaxf(fminf(inputSampleL,1.0f),-1.0f);
				float polarity = altered;
				float X = inputSampleL * altered;
				float temp = X; altered = (temp * aw_inv5); temp *= X;
				altered -= (temp * aw_inv6); temp *= X; altered += (temp * aw_inv7); temp *= X;
				altered -= (temp * aw_inv8); temp *= X; altered += (temp * aw_inv9);
				altered *= ((polarity<0.0f)?-1.0f:1.0f);
			}
			inputSampleL = (inputSampleL*(1.0f-fabsf(aw_f_topLevl-1.0f)))+(altered*fabsf(aw_f_topLevl-1.0f));
			
			altered = pearA[figL];
			if (pearA[levl] > 1.0f) {
				altered = fmaxf(fminf(pearA[figL]*(1.57079632679489661923f),(1.57079632679489661923f)),-(1.57079632679489661923f));
				float X = altered*altered;
				float temp = altered*X; altered -= (temp* aw_inv0); temp *= X;
				altered += (temp * aw_inv1); temp *= X; altered -= (temp * aw_inv2); temp *= X;
				altered += (temp * aw_inv3); temp *= X; altered -= (temp * aw_inv4);
			}
			if (pearA[levl] < 1.0f) {
				altered = fmaxf(fminf(pearA[figL],1.0f),-1.0f);
				float polarity = altered;
				float X = pearA[figL] * altered;
				float temp = X; altered = (temp * aw_inv5); temp *= X;
				altered -= (temp * aw_inv6); temp *= X; altered += (temp * aw_inv7); temp *= X;
				altered -= (temp * aw_inv8); temp *= X; altered += (temp * aw_inv9);
				altered *= ((polarity<0.0f)?-1.0f:1.0f);
			}
			inputSampleL += (pearA[figL]*(1.0f-fabsf(pearA[levl]-1.0f)))+(altered*fabsf(pearA[levl]-1.0f));
			
			altered = pearB[figL];
			if (pearB[levl] > 1.0f) {
				altered = fmaxf(fminf(pearB[figL]*(1.57079632679489661923f),(1.57079632679489661923f)),-(1.57079632679489661923f));
				float X = altered*altered;
				float temp = altered*X; altered -= (temp* aw_inv0); temp *= X;
				altered += (temp * aw_inv1); temp *= X; altered -= (temp * aw_inv2); temp *= X;
				altered += (temp * aw_inv3); temp *= X; altered -= (temp * aw_inv4);
			}
			if (pearB[levl] < 1.0f) {
				altered = fmaxf(fminf(pearB[figL],1.0f),-1.0f);
				float polarity = altered;
				float X = pearB[figL] * altered;
				float temp = X; altered = (temp * aw_inv5); temp *= X;
				altered -= (temp * aw_inv6); temp *= X; altered += (temp * aw_inv7); temp *= X;
				altered -= (temp * aw_inv8); temp *= X; altered += (temp * aw_inv9);
				altered *= ((polarity<0.0f)?-1.0f:1.0f);
			}
			inputSampleL += (pearB[figL]*(1.0f-fabsf(pearB[levl]-1.0f)))+(altered*fabsf(pearB[levl]-1.0f));
			
			altered = pearC[figL];
			if (pearC[levl] > 1.0f) {
				altered = fmaxf(fminf(pearC[figL]*(1.57079632679489661923f),(1.57079632679489661923f)),-(1.57079632679489661923f));
				float X = altered*altered;
				float temp = altered*X; altered -= (temp* aw_inv0); temp *= X;
				altered += (temp * aw_inv1); temp *= X; altered -= (temp * aw_inv2); temp *= X;
				altered += (temp * aw_inv3); temp *= X; altered -= (temp * aw_inv4);
			}
			if (pearC[levl] < 1.0f) {
				altered = fmaxf(fminf(pearC[figL],1.0f),-1.0f);
				float polarity = altered;
				float X = pearC[figL] * altered;
				float temp = X; altered = (temp * aw_inv5); temp *= X;
				altered -= (temp * aw_inv6); temp *= X; altered += (temp * aw_inv7); temp *= X;
				altered -= (temp * aw_inv8); temp *= X; altered += (temp * aw_inv9);
				altered *= ((polarity<0.0f)?-1.0f:1.0f);
			}
			inputSampleL += (pearC[figL]*(1.0f-fabsf(pearC[levl]-1.0f)))+(altered*fabsf(pearC[levl]-1.0f));
			//end FatEQ L
			
			//begin FatEQ R
			altered = inputSampleR;
			if (aw_f_topLevl > 1.0f) {
				altered = fmaxf(fminf(inputSampleR*(1.57079632679489661923f),(1.57079632679489661923f)),-(1.57079632679489661923f));
				float X = altered*altered;
				float temp = altered*X; altered -= (temp* aw_inv0); temp *= X;
				altered += (temp * aw_inv1); temp *= X; altered -= (temp * aw_inv2); temp *= X;
				altered += (temp * aw_inv3); temp *= X; altered -= (temp * aw_inv4);
			}
			if (aw_f_topLevl < 1.0f) {
				altered = fmaxf(fminf(inputSampleR,1.0f),-1.0f);
				float polarity = altered;
				float X = inputSampleR * altered;
				float temp = X; altered = (temp * aw_inv5); temp *= X;
				altered -= (temp * aw_inv6); temp *= X; altered += (temp * aw_inv7); temp *= X;
				altered -= (temp * aw_inv8); temp *= X; altered += (temp * aw_inv9);
				altered *= ((polarity<0.0f)?-1.0f:1.0f);
			}
			inputSampleR = (inputSampleR*(1.0f-fabsf(aw_f_topLevl-1.0f)))+(altered*fabsf(aw_f_topLevl-1.0f));
			
			altered = pearA[figR];
			if (pearA[levl] > 1.0f) {
				altered = fmaxf(fminf(pearA[figR]*(1.57079632679489661923f),(1.57079632679489661923f)),-(1.57079632679489661923f));
				float X = altered*altered;
				float temp = altered*X; altered -= (temp* aw_inv0); temp *= X;
				altered += (temp * aw_inv1); temp *= X; altered -= (temp * aw_inv2); temp *= X;
				altered += (temp * aw_inv3); temp *= X; altered -= (temp * aw_inv4);
			}
			if (pearA[levl] < 1.0f) {
				altered = fmaxf(fminf(pearA[figR],1.0f),-1.0f);
				float polarity = altered;
				float X = pearA[figR] * altered;
				float temp = X; altered = (temp * aw_inv5); temp *= X;
				altered -= (temp * aw_inv6); temp *= X; altered += (temp * aw_inv7); temp *= X;
				altered -= (temp * aw_inv8); temp *= X; altered += (temp * aw_inv9);
				altered *= ((polarity<0.0f)?-1.0f:1.0f);
			}
			inputSampleR += (pearA[figR]*(1.0f-fabsf(pearA[levl]-1.0f)))+(altered*fabsf(pearA[levl]-1.0f));
			
			altered = pearB[figR];
			if (pearB[levl] > 1.0f) {
				altered = fmaxf(fminf(pearB[figR]*(1.57079632679489661923f),(1.57079632679489661923f)),-(1.57079632679489661923f));
				float X = altered*altered;
				float temp = altered*X; altered -= (temp* aw_inv0); temp *= X;
				altered += (temp * aw_inv1); temp *= X; altered -= (temp * aw_inv2); temp *= X;
				altered += (temp * aw_inv3); temp *= X; altered -= (temp * aw_inv4);
			}
			if (pearB[levl] < 1.0f) {
				altered = fmaxf(fminf(pearB[figR],1.0f),-1.0f);
				float polarity = altered;
				float X = pearB[figR] * altered;
				float temp = X; altered = (temp * aw_inv5); temp *= X;
				altered -= (temp * aw_inv6); temp *= X; altered += (temp * aw_inv7); temp *= X;
				altered -= (temp * aw_inv8); temp *= X; altered += (temp * aw_inv9);
				altered *= ((polarity<0.0f)?-1.0f:1.0f);
			}
			inputSampleR += (pearB[figR]*(1.0f-fabsf(pearB[levl]-1.0f)))+(altered*fabsf(pearB[levl]-1.0f));
			
			altered = pearC[figR];
			if (pearC[levl] > 1.0f) {
				altered = fmaxf(fminf(pearC[figR]*(1.57079632679489661923f),(1.57079632679489661923f)),-(1.57079632679489661923f));
				float X = altered*altered;
				float temp = altered*X; altered -= (temp* aw_inv0); temp *= X;
				altered += (temp * aw_inv1); temp *= X; altered -= (temp * aw_inv2); temp *= X;
				altered += (temp * aw_inv3); temp *= X; altered -= (temp * aw_inv4);
			}
			if (pearC[levl] < 1.0f) {
				altered = fmaxf(fminf(pearC[figR],1.0f),-1.0f);
				float polarity = altered;
				float X = pearC[figR] * altered;
				float temp = X; altered = (temp * aw_inv5); temp *= X;
				altered -= (temp * aw_inv6); temp *= X; altered += (temp * aw_inv7); temp *= X;
				altered -= (temp * aw_inv8); temp *= X; altered += (temp * aw_inv9);
				altered *= ((polarity<0.0f)?-1.0f:1.0f);
			}
			inputSampleR += (pearC[figR]*(1.0f-fabsf(pearC[levl]-1.0f)))+(altered*fabsf(pearC[levl]-1.0f));
			//end FatEQ R
		}
		
		inputSampleL *= aw_f_out;
		inputSampleR *= aw_f_out;

		//begin ClipOnly2 stereo as a little, compressed chunk that can be dropped into code
		if (inputSampleL > 4.0f) inputSampleL = 4.0f; if (inputSampleL < -4.0f) inputSampleL = -4.0f;
		if (wasPosClipL == true) { //current will be over
			if (inputSampleL<lastSampleL) lastSampleL=0.7058208f+(inputSampleL*0.2609148f);
			else lastSampleL = 0.2491717f+(lastSampleL*0.7390851f);
		} wasPosClipL = false;
		if (inputSampleL>0.9549925859f) {wasPosClipL=true;inputSampleL=0.7058208f+(lastSampleL*0.2609148f);}
		if (wasNegClipL == true) { //current will be -over
			if (inputSampleL > lastSampleL) lastSampleL=-0.7058208f+(inputSampleL*0.2609148f);
			else lastSampleL=-0.2491717f+(lastSampleL*0.7390851f);
		} wasNegClipL = false;
		if (inputSampleL<-0.9549925859f) {wasNegClipL=true;inputSampleL=-0.7058208f+(lastSampleL*0.2609148f);}
		intermediateL[spacing] = inputSampleL;
        inputSampleL = lastSampleL; //Latency is however many samples equals one 44.1k sample
		for (int x = spacing; x > 0; x--) intermediateL[x-1] = intermediateL[x];
		lastSampleL = intermediateL[0]; //run a little buffer to handle this
		
		if (inputSampleR > 4.0f) inputSampleR = 4.0f; if (inputSampleR < -4.0f) inputSampleR = -4.0f;
		if (wasPosClipR == true) { //current will be over
			if (inputSampleR<lastSampleR) lastSampleR=0.7058208f+(inputSampleR*0.2609148f);
			else lastSampleR = 0.2491717f+(lastSampleR*0.7390851f);
		} wasPosClipR = false;
		if (inputSampleR>0.9549925859f) {wasPosClipR=true;inputSampleR=0.7058208f+(lastSampleR*0.2609148f);}
		if (wasNegClipR == true) { //current will be -over
			if (inputSampleR > lastSampleR) lastSampleR=-0.7058208f+(inputSampleR*0.2609148f);
			else lastSampleR=-0.2491717f+(lastSampleR*0.7390851f);
		} wasNegClipR = false;
		if (inputSampleR<-0.9549925859f) {wasNegClipR=true;inputSampleR=-0.7058208f+(lastSampleR*0.2609148f);}
		intermediateR[spacing] = inputSampleR;
        inputSampleR = lastSampleR; //Latency is however many samples equals one 44.1k sample
		for (int x = spacing; x > 0; x--) intermediateR[x-1] = intermediateR[x];
		lastSampleR = intermediateR[0];
		fpdL ^= fpdL << 13; fpdL ^= fpdL >> 17; fpdL ^= fpdL << 5;
		fpdR ^= fpdR << 13; fpdR ^= fpdR >> 17; fpdR ^= fpdR << 5;
		//end 32 bit stereo floating point dither
		
		aw_outL = inputSampleL;
		aw_outR = inputSampleR;
    /* aw:end */		AW_OUT_FAST(aw_out, aw_channels, aw_outL, aw_outR);
		aw_in += aw_channels;
		aw_out += aw_channels;
	}
}
    aw_s->lastSampleL = lastSampleL;
    aw_s->wasPosClipL = wasPosClipL;
    aw_s->wasNegClipL = wasNegClipL;
    aw_s->lastSampleR = lastSampleR;
    aw_s->wasPosClipR = wasPosClipR;
    aw_s->wasNegClipR = wasNegClipR;
    aw_s->fpdL = fpdL;
    aw_s->fpdR = fpdR;
}

static const uint32_t aw_FatEQ_offsets_fast[] = {offsetof(aw_FatEQ_fast_t, A), offsetof(aw_FatEQ_fast_t, B), offsetof(aw_FatEQ_fast_t, C), offsetof(aw_FatEQ_fast_t, D), offsetof(aw_FatEQ_fast_t, E)};
#endif

